template <int Flags>
struct Configuration {
    // NTTP used for compile-time logic and branch elimination
    static constexpr bool IsOptimized = (Flags & 0x1);
};

// C++20: Literal Class Type as NTTP
struct CompileTimeId {
    int value;
    constexpr CompileTimeId(int v) : value(v) {}
};

template <CompileTimeId ID>
class Processor {
    // Compiler generates distinct code per ID.value
    static_assert(ID.value > 0);
};

constexpr CompileTimeId KeyA{100};
constexpr CompileTimeId KeyB{200};

Processor<KeyA> p1;
Processor<KeyB> p2; // Separate instantiation
Configuration<3> c; // IsOptimized = true
Configuration<2> d; // IsOptimized = false
